using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;
namespace GearLab {public static class Industrial66NativeTests {
 public static int Run(string folder){Directory.CreateDirectory(folder);var log=new StringBuilder();int count=0;Action<bool,string> check=(v,m)=>{if(!v)throw new Exception(m);count++;log.AppendLine("PASS "+m);};try{
 string root=Path.GetDirectoryName(System.Windows.Forms.Application.ExecutablePath);string file=Path.Combine(root,"examples","Industrial_1000mm.robot.json");if(!File.Exists(file))file=Path.Combine(Path.GetDirectoryName(root),"examples","Industrial_1000mm.robot.json");var doc=RobotDocument.Parse(File.ReadAllText(file));
 foreach(var j in doc.Joints){check(j.GeneratedBody!=null&&j.GeneratedBody.Result.GeometryValid,"valid native body "+j.Id);check(j.GeneratedBody.Fingerprint==ProceduralBodySpec.Fingerprint(doc,j,j.BodyGenerator),"current CAD parameters "+j.Id);check(j.GeneratedBody.Result.Mates.All(m=>m.BoresVerified),"real flange bores "+j.Id);check(!j.GeneratedBody.Result.ReadyForManufacture,"no false manufacturing approval "+j.Id);foreach(var p in j.GeneratedBody.Result.Parts.Where(p=>p.Role!="hardware"&&p.Role!="insert"&&p.Role!="metal"))check(j.GeneratedBody.Result.Issues.Any(i=>i.Code=="printer"&&i.PartId==p.Id&&i.Status=="pass"),"individual P1S envelope "+j.Id+" / "+p.Id);}
 check(IndustrialRobot66.ForWorkspace(1000,.3).Joints.All(j=>j.GeneratedBody!=null),"workspace opens actual cached independent CAD");var build=RobotCad.Build(doc);check(build.Model.Valid,"assembled CAD valid");check(build.Entries.Values.Count(e=>e.Part.BearingSource!=null&&e.Part.BearingElement==1&&!e.InputSide)>=12,"inner bearing rings follow output shafts");check(build.Entries.Values.Count(e=>e.BearingGain>0&&e.BearingGain<.5)>12,"rolling elements and cages have relative motion");check(RobotConnections.Validate(build).Count==0,"all world flange frames coincide");check(build.Entries.Keys.Count(k=>k.Contains("rear_bearing"))>=12,"second bearing expands into actual bearing parts");
 var random=new Random(66);for(int n=0;n<24;n++){foreach(var j in doc.Joints)j.Position=j.Minimum+(j.Maximum-j.Minimum)*random.NextDouble();build.InvalidatePose();check(RobotConnections.Validate(build).Count==0,"flanges remain joined in pose "+n);}foreach(var j in doc.Joints)j.Position=0;build.InvalidatePose();
 using(var kernel=new CADKernel()){
 File.AppendAllText(Path.Combine(folder,"native-progress.txt"),"Preparing exact assembly STEP parts\r\n");var parts=build.Entries.Values.Where(e=>!e.Guide&&e.Category!="Крепёж"&&e.Category!="Проводка").Select(e=>new{Id=e.Id,Step=e.Part.Analytic==null?CADNativeBridge.FromLegacyPart(e.Part).Features[0].Data:null,Analytic=e.Part.Analytic,Transform=CADNativeBridge.Transform(build.Pose(e.Id,0,false)),Integral=e.Category=="Мотор"?e.JointId+"_motor_integral":null}).ToArray();File.WriteAllText(Path.Combine(folder,"industrial66-contact-request.json"),CADDocument.Serializer().Serialize(new{Spec=new{Parts=parts}}),Encoding.UTF8);File.AppendAllText(Path.Combine(folder,"native-progress.txt"),"Checking upright assembly\r\n");var contacts=kernel.Run(new CADDocument(),"assembly_contacts",null,null,null,new Dictionary<string,object>{{"Spec",new{Parts=parts}}}).Motion;File.WriteAllText(Path.Combine(folder,"industrial66-contacts-results.json"),CADDocument.Serializer().Serialize(contacts),Encoding.UTF8);check(contacts.Status=="clear","assembled exact CAD intersection check: "+string.Join("; ",contacts.Collisions.Select(c=>c.A+" / "+c.B+" "+c.Volume)));
 var steps=parts.ToDictionary(p=>p.Id,p=>p.Step);double[] q={0,30,-60,0,30,0};for(int i=0;i<6;i++)doc.Joints[i].Position=q[i];build.InvalidatePose();var bentParts=build.Entries.Values.Where(e=>!e.Guide&&e.Category!="Крепёж"&&e.Category!="Проводка"&&e.Part.BearingSource==null).Select(e=>new{Id=e.Id,Step=steps[e.Id],Transform=CADNativeBridge.Transform(build.Pose(e.Id,0,false)),Integral=e.Category=="Мотор"?e.JointId+"_motor_integral":null}).ToArray();File.AppendAllText(Path.Combine(folder,"native-progress.txt"),"Checking bent housings\r\n");var bent=kernel.Run(new CADDocument(),"assembly_contacts",null,null,null,new Dictionary<string,object>{{"Spec",new{Parts=bentParts}}}).Motion;File.WriteAllText(Path.Combine(folder,"industrial66-bent-housings-results.json"),CADDocument.Serializer().Serialize(bent),Encoding.UTF8);check(bent.Status=="clear","bent housing and shaft CAD intersection check: "+string.Join("; ",bent.Collisions.Select(c=>c.A+" / "+c.B+" "+c.Volume)));foreach(var j in doc.Joints)j.Position=0;build.InvalidatePose();
 var changed=doc.Clone();var j3=changed.Joints[2];var port=j3.GeneratedBody.Result.Mates.First(m=>m.Id=="link_child");double volume=j3.GeneratedBody.Result.Parts.Where(p=>p.Role=="frame").Sum(p=>p.Volume);j3.EndZ+=20;bool staleBlocked=false;try{RobotCad.Build(changed).ForExport(true,null);}catch{staleBlocked=true;}check(staleBlocked,"dimension edit blocks stale CAD export");File.AppendAllText(Path.Combine(folder,"native-progress.txt"),"Regenerating longer link\r\n");j3.GeneratedBody=ProceduralBodySpec.Generate(kernel,changed,j3,j3.BodyGenerator);check(j3.GeneratedBody.Result.GeometryValid,"longer actual link regenerates as valid native solids");check(Math.Abs(j3.GeneratedBody.Result.Parts.Where(p=>p.Role=="frame").Sum(p=>p.Volume)-volume)>10,"actual structural volume changes");var next=j3.GeneratedBody.Result.Mates.First(m=>m.Id=="link_child");check(Math.Sqrt(port.Origin.Zip(next.Origin,(a,b)=>(a-b)*(a-b)).Sum())>19.9,"actual child flange moves with length");var resized=RobotCad.Build(changed);check(RobotConnections.Validate(resized).Count==0,"regenerated child flange mates without disconnected parts");
 }
 File.AppendAllText(Path.Combine(folder,"native-progress.txt"),"Exporting separate prototype STL parts\r\n");PrintExport.Zip(build.ForExport(true,null),Path.Combine(folder,"Industrial_PROTOTYPE_STL.zip"));check(new FileInfo(Path.Combine(folder,"Industrial_PROTOTYPE_STL.zip")).Length>1000,"separate prototype STL export");using(var zip=System.IO.Compression.ZipFile.OpenRead(Path.Combine(folder,"Industrial_PROTOTYPE_STL.zip")))foreach(var entry in zip.Entries.Where(e=>e.Name.EndsWith(".stl",StringComparison.OrdinalIgnoreCase))){using(var stream=entry.Open())using(var reader=new BinaryReader(stream)){reader.ReadBytes(80);uint triangles=reader.ReadUInt32();double[] lo={double.MaxValue,double.MaxValue,double.MaxValue},hi={double.MinValue,double.MinValue,double.MinValue};for(uint t=0;t<triangles;t++){reader.ReadBytes(12);for(int v=0;v<3;v++)for(int axis=0;axis<3;axis++){double value=reader.ReadSingle();lo[axis]=Math.Min(lo[axis],value);hi[axis]=Math.Max(hi[axis],value);}reader.ReadUInt16();}check(Enumerable.Range(0,3).All(i=>hi[i]-lo[i]<=250),"actual oriented STL fits P1S: "+entry.Name);}}
 File.WriteAllText(Path.Combine(folder,"industrial66-native-results.txt"),log+"PASS "+count+" assertions",Encoding.UTF8);return 0;
 }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"industrial66-native-error.txt"),log.ToString()+ex.ToString(),Encoding.UTF8);return 1;}
 }
}}
